function(...args) {
      native.call("hash.split", this, projected, args);
      assert.equal(this, projected);
      assert.deepEqual(args, [":"]);
      if (scenario.split === "throws")
        throw original;
      if (scenario.split === "empty")
        return [];
      if (scenario.split === "string")
        return "ab";
      if (scenario.split === "number-key")
        return ["salt", 17];
      if (scenario.split === "number-salt")
        return [17, "wrong-key"];
      return ["salt", "wrong-key"];
    }

